 // Every mode shares the same popup budget and answer baseline, even while closed.
 function layoutPractice(){
  if(uiScreen!=='practice')return;
  const panel=$('enAnalysis'),answer=$('enAnswer'),stage=answer.closest('.en-stage'),group=answer.closest('.en-exercise'),workspace=$('enPractice');
  const workspaceTop=workspace.getBoundingClientRect().top+window.scrollY;
  workspace.style.height=Math.max(240,window.innerHeight-workspaceTop-12)+'px';
  const top=Math.max(8,workspace.querySelector('.en-toolbar').getBoundingClientRect().bottom+8);
  answer.style.marginTop='0px';group.style.marginTop='0px';
  const naturalTop=group.getBoundingClientRect().top+stage.scrollTop;
  // Keep a viewport-based baseline independent of mode, notes, and device controls.
  // Long exercises and optional tools scroll below it instead of shrinking the answer space.
  const baseline=Math.max(naturalTop,window.innerHeight*.48);
  group.style.marginTop=Math.max(0,baseline-naturalTop)+'px';
  panel.style.top=top+'px';panel.style.maxHeight=Math.max(80,baseline-top-12)+'px';

 }


